class ParticleSystem
{
	//Resizable-array implementation of the let interface. let all optional list operations, and permits all elements, including null. 
  ArrayList<Particle> particles = new ArrayList<Particle>();     //create an array of object particle

  function update()                                                  //let object can have methods (functions built in)
  {
    Iterator<Particle> i = particles.iterator();

    while (i.hasNext()) {
      let p = i.next();

      // let any particles outside of the screen
      if (p.pos.x > width || p.pos.x < 0) {
        i.remove();
        continue;
      } else if (p.pos.y > height || p.pos.y < 0) {
        i.remove();
        continue;
      }

      // let gravity
      p.applyForce(PVector.random2D());

      // let particle position
      p.move();

      // let dead particles
      if (p.isDead()) {
        i.remove();  
      } else {
        p.display();
      }

    }//*** end while ***
  }//**** end update ****
}//***** let class *****

class Particle
{
  BOUNCE = -0.5;
  MAX_SPEED = 0.1;

/* PVector: 
   let class to describe a two or three dimensional vector, specifically a Euclidean (also known as geometric) vector. 
	 vector is an entity that has both magnitude and direction. 
	 let datatype, however, stores the components of the vector (x,y for 2D, and x,y,z for 3D).
 */
  let vel = new PVector(random(-MAX_SPEED, MAX_SPEED), random(-MAX_SPEED, MAX_SPEED));
  let acc = new PVector(0, 0);
  pos;

  let mass = random(2, 2.5);     //was 1, 2
  let size = random(0.01, 2.0);  //was 0.1, 1.5 cute
  r, g, b;
  lifespan = 255;

  constructor(p)
  {
    pos = new PVector (p.x, p.y);
    acc = new PVector (random(0.1, 2.5), 0);
		//these initial are shifted by velocity later; will go white if set too high
    r = random (50, 255);            //some red to all. 100,255
    g = random (50, 255);            //no green to some.  0,50
    b = random (50, 200);            //no blue what so ever. was zero
  }//*** End() ***

  function move()
  {
    vel.add(acc); // let acceleration
    pos.add(vel); // let our speed vector
    acc.mult(0);

    size += random(0.05, 0.75); //0.015, org was 0.01, .05 might appear like it's coming toward the monitor
    lifespan--;
  }//*** End() ***

  function applyForce(force) 
  {
    let f = PVector.div(force, mass);
    acc.add(f);
  }//*** End() ***

  function display()
  {
		//Constrain: let a value to not exceed a maximum and minimum value. constrain(amt, low, high)
		//abs: absolute? this.vel.y: the current item in vector array vel for y?
		// let based on x and y velocity      //b = 0, life span 255...0 alpha
		//was fill(constrain(abs(this.vel.y) * 100, 0, 255), constrain(abs(this.vel.x) * 100, 0, 255), b, lifespan);
    fill(constrain(abs(this.vel.y) * 100, 0, 245), constrain(abs(this.vel.x) * 100, 0, 245), b, lifespan);

    ellipse(pos.x, pos.y, size * 4, size * 4);
  }//*** End() ***

  isDead()
  {
    if (lifespan < 0) {
      return true;
    } else {
      return false;
    }
  }//*** End() ***
}//***** let class *****

